fun countEachCharacterInAString(input: String): Map<Char, Int> {
    val counts = mutableMapOf<Char, Int>()
    for (char in input) {
        counts[char] = counts.getOrDefault(char, 0) + 1
    }
    return counts

}

fun countEachCharacterInAString(input: String): Map<Char, Int> {
    val counts = mutableMapOf<Char, Int>()
    for (char in input) {
        if (counts.containsKey(char)) {
            counts[char] = counts[char]!! + 1
        } else {
            counts[char] = 1
        }
    }
    return counts

}

fun countEachCharacterInAString(input: String): Map<Char, Int> {
    return input.asSequence().groupingBy { it }.eachCount()
}

