public static Map<Character, Integer> countEachCharacterInAString(String input) {
    return input.chars().mapToObj(c -> (char) c).collect(Collectors.groupingBy(c -> c, LinkedHashMap::new, Collectors.summingInt(c -> 1)));
 }

